def qparts(qid):
    if not isinstance(qid,str):
        return []
    return qid.split(':')


def grounded(answer,unit_text):
    support=[]
    quotes=[]
    evidence=answer.get('evidence',[])
    if isinstance(evidence,dict):
        evidence=[evidence]
    if isinstance(evidence,list):
        for item in evidence:
            if isinstance(item,dict):
                uid=item.get('unit_id')
                quote=item.get('quote')
                if isinstance(uid,int) and uid in unit_text and uid not in support:
                    support.append(uid)
                if isinstance(quote,str) and quote:
                    quotes.append(quote)
    selected=answer.get('selected_evidence_unit_ids',[])
    if isinstance(selected,list):
        for uid in selected:
            if isinstance(uid,int) and uid in unit_text and uid not in support:
                support.append(uid)
    if not quotes:
        for uid in support:
            text=unit_text.get(uid,'')
            if text:
                quotes.append(text)
    return support,' || '.join(quotes)


def union_participants(values):
    if not values:
        return None
    value=values[0]
    i=1
    while i<len(values):
        value=['participant_union',value,values[i]]
        i+=1
    return value


def combine_triggers(values):
    out=[]
    for value in values:
        if value not in out:
            out.append(value)
    if not out:
        return None
    value=out[0]
    i=1
    while i<len(out):
        value=['trigger_alternative',value,out[i]]
        i+=1
    return value


def add_statement(statements,keys,term,support):
    support=sorted(set(support))
    key=repr(term)+'|'+repr(support)
    if support and key not in keys:
        keys.add(key)
        statements.append({'term':term,'support_ids':support})


def complete_ids(answer):
    record=answer.get('complete_source_evidence')
    if isinstance(record,dict):
        ids=record.get('unit_ids',[])
        if isinstance(ids,list):
            return ids
    return []


def apply(inputs,premises):
    spans=inputs.get('source_spans',[])
    answers=inputs.get('semantic_answers',[])
    unit_text={}
    order=[]
    for span in spans:
        uid=span.get('id')
        text=span.get('text','')
        if isinstance(uid,int) and isinstance(text,str):
            unit_text[uid]=text
            order.append(uid)
    statements=[]
    keys=set()
    unresolved=[]
    actions={}
    triggers={}
    retentions=[]
    audits={}
    disclosure_permissions=0
    disposal_count=0
    retention_count=0
    ci=['confidential_information']
    receiver=['receiving_party']
    discloser=['disclosing_party']
    for answer in answers:
        if not isinstance(answer,dict):
            continue
        qid=answer.get('id')
        operation=answer.get('operation')
        choice=answer.get('choice')
        if not isinstance(qid,str):
            continue
        if choice is None or choice=='unknown':
            unresolved.append('Unresolved semantic reading: '+qid)
            continue
        support,quote=grounded(answer,unit_text)
        parts=qparts(qid)
        if operation in ('disclosure_permission_audit','disposal_obligation_audit','retention_effect_audit'):
            audits[operation]=answer
            continue
        if not support:
            unresolved.append('Definite reading lacks grounded current-source evidence: '+qid)
            continue
        if operation=='disclosure_clause':
            recipients=None
            if choice=='affiliate_personnel_permission':
                owner=['affiliates_of',receiver]
                recipients=union_participants([['employees_of',owner],['directors_of',owner],['officers_of',owner]])
            elif choice=='internal_employee_officer_director_permission':
                recipients=union_participants([['employees_of',receiver],['directors_of',receiver],['officers_of',receiver]])
            elif choice=='internal_employee_director_contractor_permission':
                recipients=union_participants([['employees_of',receiver],['directors_of',receiver],['independent_contractors_of',receiver]])
            elif choice=='own_and_controlled_personnel_permission':
                controlled=['controlled_entities_of',receiver]
                recipients=union_participants([['internal_personnel_of',receiver],['agents_of',receiver],['internal_personnel_of',controlled],['agents_of',controlled]])
            elif choice=='professional_service_recipient_permission':
                recipients=union_participants([['consultants_of',receiver],['agents_of',receiver],['independent_contractors_of',receiver],['professional_advisors_of',receiver]])
            if recipients is not None:
                condition=['and_condition',['need_to_know',quote],['confidentiality_bound',quote]]
                add_statement(statements,keys,['permission',receiver,['disclose',ci,recipients],condition],support)
                disclosure_permissions+=1
            elif choice=='general_third_party_prohibition':
                add_statement(statements,keys,['prohibition',receiver,['disclose',ci,['third_parties']],['no_condition'],['no_exceptions']],support)
            elif choice=='other_relevant_clause':
                unresolved.append('Unsupported operative disclosure meaning: '+qid)
            elif choice!='not_relevant_or_nonoperative':
                unresolved.append('Unrecognized disclosure choice: '+qid)
        elif operation=='disposal_action_scope':
            if len(parts)<2 or not parts[-1].isdigit():
                unresolved.append('Malformed dynamic disposal action identity: '+qid)
                continue
            anchor=int(parts[-1])
            if choice=='other_disposal_action':
                unresolved.append('Unsupported disposal action: '+qid)
            elif choice!='not_disposal_action':
                actions[anchor]={'choice':choice,'support':support,'quote':quote,'id':qid}
        elif operation=='disposal_trigger':
            if len(parts)<3 or not parts[-2].isdigit():
                unresolved.append('Malformed dynamic disposal trigger identity: '+qid)
                continue
            anchor=int(parts[-2])
            term=None
            if choice=='agreement_termination_or_request':
                term=['trigger_alternative',['agreement_termination'],['request_by',discloser]]
            elif choice=='purpose_completion_or_request':
                term=['trigger_alternative',['purpose_completion'],['request_by',discloser]]
            elif choice=='relationship_nonformation_deadline':
                term=['relationship_nonformation_deadline']
            elif choice=='relationship_termination':
                term=['relationship_termination']
            elif choice=='agreement_termination':
                term=['agreement_termination']
            elif choice=='purpose_completion':
                term=['purpose_completion']
            elif choice=='request_by_discloser':
                term=['request_by',discloser]
            elif choice=='other_disposal_trigger':
                unresolved.append('Unsupported disposal trigger: '+qid)
            elif choice!='not_disposal_trigger':
                unresolved.append('Unrecognized disposal trigger choice: '+qid)
            if term is not None:
                triggers.setdefault(anchor,[]).append({'term':term,'support':support,'quote':quote,'id':qid})
        elif operation=='retention_clause':
            if len(parts)<2 or not parts[-1].isdigit():
                unresolved.append('Malformed dynamic retention identity: '+qid)
                continue
            anchor=int(parts[-1])
            if choice=='archival_copy_permission':
                term=['retention_permission',receiver,['copies_of',ci],['after_disposal'],['retention_condition',quote]]
                add_statement(statements,keys,term,support)
                retentions.append({'anchor':anchor,'choice':choice,'support':support,'quote':quote})
                retention_count+=1
            elif choice=='explicit_post_disposal_retention_prohibition':
                add_statement(statements,keys,['retention_prohibition',receiver,ci,['after_disposal']],support)
                retentions.append({'anchor':anchor,'choice':choice,'support':support,'quote':quote})
                retention_count+=1
            elif choice=='other_explicit_retention_effect':
                unresolved.append('Unsupported explicit retention effect: '+qid)
            elif choice!='no_retention_effect_in_this_unit':
                unresolved.append('Unrecognized retention choice: '+qid)
    for anchor,record in actions.items():
        choice=record['choice']
        bundle=['information_bundle',ci,['copies_of',ci]]
        if choice=='return_or_destroy_information_copies_and_derivatives':
            bundle=['information_bundle',bundle,['derivative_materials_of',ci]]
        returned=['return_to',bundle,discloser]
        destroyed=['destroy',bundle]
        action=None
        if choice=='return_all_documents_materials_and_copies':
            action=returned
        elif choice in ('return_or_destroy_all_information_and_copies','return_or_destroy_information_copies_and_derivatives'):
            action=['source_action_alternative',returned,destroyed,record['quote']]
        elif choice=='return_or_destroy_all_information_and_copies_at_discloser_choice':
            action=['action_alternative',returned,destroyed]
        elif choice=='return_or_authorized_destroy_all_information_and_copies':
            action=['source_authorized_action_alternative',returned,destroyed,record['quote']]
        else:
            unresolved.append('Unrecognized disposal action choice: '+record['id'])
            continue
        trigger_rows=triggers.get(anchor,[])
        trigger=combine_triggers([row['term'] for row in trigger_rows])
        if trigger is None:
            unresolved.append('Disposal action lacks a definite acquired trigger: '+record['id'])
            continue
        support=list(record['support'])
        for row in trigger_rows:
            support.extend(row['support'])
        exceptions=['no_exceptions']
        for retention in retentions:
            if retention['choice']=='archival_copy_permission' and retention['anchor']==anchor:
                exception=['retention_exception',receiver,['copies_of',ci],['retention_condition',retention['quote']]]
                exceptions=['exception_set',exception]
                support.extend(retention['support'])
        add_statement(statements,keys,['disposal_obligation',receiver,action,trigger,exceptions],support)
        disposal_count+=1
    audit_specs=[('disclosure_permission_audit','no_operative_internal_or_service_permission','complete_source_no_disclosure_permission',disclosure_permissions),('disposal_obligation_audit','no_operative_disposal_obligation','complete_source_no_disposal_obligation',disposal_count),('retention_effect_audit','no_explicit_post_disposal_retention_effect','complete_source_no_retention_effect',retention_count)]
    for operation,absence_choice,constructor,count in audit_specs:
        answer=audits.get(operation)
        if answer is None:
            unresolved.append('Missing complete-source audit: '+operation)
            continue
        choice=answer.get('choice')
        if choice==absence_choice:
            inspected=complete_ids(answer)
            if not order or set(inspected)!=set(order):
                unresolved.append('Incomplete explicit source inspection for absence: '+operation)
            else:
                add_statement(statements,keys,[constructor],order)
        elif choice=='category_present':
            if count==0:
                unresolved.append('Audit found a category without a definite classified clause: '+operation)
        elif choice=='unknown' or choice is None:
            unresolved.append('Unresolved complete-source audit: '+operation)
        else:
            unresolved.append('Unrecognized complete-source audit choice: '+operation)
    clean=[]
    for item in unresolved:
        if item not in clean:
            clean.append(item)
    return {'statements':statements,'complete':len(clean)==0,'unresolved':clean}

